from pathlib import Path
import re,json
root=Path(__file__).resolve().parent
out=root/'review';out.mkdir(exist_ok=True)
# This theme uses a flat mapping plus light/dark mappings, all scalar strings.
theme={}; modes={'light':{},'dark':{}}; mode=None
for line in (root/'themes/eleven_material.yaml').read_text().splitlines():
 if not line.strip() or line.lstrip().startswith('#'):continue
 if line.startswith('    light:'):mode='light';continue
 if line.startswith('    dark:'):mode='dark';continue
 if line.strip() in ['Eleven Material:','modes:']:continue
 k,v=line.strip().split(':',1);v=v.strip()
 if v.startswith('"'):v=json.loads(v)
 (modes[mode] if mode else theme)[k]=v
base={'primary-color':'#03a9f4','accent-color':'#03a9f4','error-color':'#db4437','warning-color':'#ffa600','text-primary-color':'#fff','ha-card-border-width':'1px'}
s=(root/'tests/fixtures/theme-following.html').read_text().replace('../../','../')
s=s.replace('Eleven Cards — lokale themacontrole','Eleven Material — alle kaarten')
s=s.replace('<h1>Eleven Cards — thema volgt Home Assistant</h1><p>Synthetische lokale fixtures, geen verbinding met Home Assistant, geen installatie. De House Card is uitgesloten.</p>','<header><div><span class="eyebrow">ELEVEN MATERIAL · ONTWERPPREVIEW</span><h1>Alle kaarten, één materiaalbasis</h1><p>17 kaarttypen · 18 voorbeelden inclusief Auto met EVCC. Voorbeelddata; geen verbinding met je huis. De House Card is al goedgekeurd.</p></div><button id="mode" type="button" aria-pressed="false">Donker thema</button></header><nav aria-label="Kaarten"></nav>')
s=s.replace('</style>','''body{padding:32px clamp(16px,3vw,48px);max-width:1600px;margin:auto}header{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:24px}h1{font-size:clamp(24px,3vw,36px);line-height:1.15;margin:8px 0 12px;letter-spacing:-.7px}header p{font-size:14px;max-width:700px;color:var(--secondary-text-color)}.eyebrow{font-size:11px;letter-spacing:1.7px;color:var(--secondary-text-color)}button,nav a{font:inherit;color:var(--primary-text-color);background:var(--card-background-color);border:1px solid var(--divider-color);border-radius:12px;padding:12px 16px;text-decoration:none}button{cursor:pointer;white-space:nowrap;box-shadow:var(--ha-card-box-shadow)}button:focus-visible,nav a:focus-visible{outline:2px solid var(--accent-color);outline-offset:3px}nav{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:32px}nav a{font-size:12px;padding:8px 12px}main{gap:28px 24px;grid-template-columns:repeat(auto-fit,minmax(min(100%,360px),1fr))}article{scroll-margin-top:20px}article>h2{font-size:12px;font-weight:500;color:var(--secondary-text-color);margin:0 0 10px 4px}article>[data-chart]{height:440px}article>[data-card=timeline-card]{height:auto;min-height:300px}@media(max-width:600px){body{padding:20px 14px}header{align-items:flex-start;flex-direction:column}header button{align-self:flex-start}nav{gap:6px;margin-bottom:24px}main{gap:24px}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}</style>''')
s=s.replace('</style>', '''main.review-groups{display:block}.review-section+.review-section{margin-top:48px;padding-top:28px;border-top:1px solid var(--divider-color)}.review-section>h2{font-size:22px;line-height:1.3;margin:0 0 8px}.review-section>p{font-size:14px;line-height:1.5;color:var(--secondary-text-color);margin:0 0 24px}.review-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,360px),1fr));gap:28px 24px;align-items:start}.review-grid>article{min-width:0}.review-nav-group{display:flex;flex-wrap:wrap;gap:8px;width:100%;align-items:center}.review-nav-group>span{flex-basis:100%;font-size:12px;font-weight:600;color:var(--secondary-text-color);margin:8px 0 2px}@media(max-width:600px){.review-grid{gap:24px}.review-section+.review-section{margin-top:36px}}</style>''')
inline=re.findall(r'<script(?: type="module")?>(.*?)</script>',s,re.S);assert len(inline)==2
s=s.replace('<script>'+inline[0]+'</script>','<script src="ha-stub.js"></script>').replace('<script type="module">'+inline[1]+'</script>','<script type="module" src="gallery.js"></script>')
icons=json.loads((out/'icon-paths.json').read_text())
icon_js='const iconPaths='+json.dumps(icons)+';\n'+'''customElements.define('ha-icon',class extends HTMLElement{static get observedAttributes(){return ['icon']}constructor(){super();this.attachShadow({mode:'open'})}connectedCallback(){this.paint()}attributeChangedCallback(){this.paint()}paint(){this.shadowRoot.innerHTML='<style>:host{display:inline-flex;width:var(--mdc-icon-size,24px);height:var(--mdc-icon-size,24px);align-items:center;justify-content:center;vertical-align:middle}svg{width:100%;height:100%;fill:currentColor}</style><svg viewBox="0 0 24 24" aria-hidden="true"><path d="'+(iconPaths[this.getAttribute('icon')]||'')+'"></path></svg>'}});'''
(out/'ha-stub.js').write_text(inline[0]+icon_js)
js='const theme='+json.dumps(theme)+',modes='+json.dumps(modes)+',base='+json.dumps(base)+';\n'
js+='''function applyTheme(dark){const values={...base,...theme,...modes[dark?'dark':'light']};for(const[k,v]of Object.entries(values))document.body.style.setProperty('--'+k,v);document.body.style.colorScheme=dark?'dark':'light';document.querySelector('#mode').textContent=dark?'Licht thema':'Donker thema';document.querySelector('#mode').setAttribute('aria-pressed',String(dark));for(const r of window.records||[]){r.hass={...r.hass,themes:{darkMode:dark}};r.card.hass=r.hass;}window.reviewDark=dark;}
applyTheme(false);document.querySelector('#mode').addEventListener('click',()=>applyTheme(!window.reviewDark));
'''
# Preview-only car image: user-supplied transparent art, synthetic vehicle data.
# Keep the image outside production bundles and only allowlist this exact asset.
# Parent integration plan: trim transparent margins without changing car pixels,
# use existing image-entity configuration, preserve all other fixtures, then
# check composed served preview and status counts at mobile/dashboard widths.
# Preview-only actions: enough examples to assess rows, wrapping and spacing.
action_examples=[('scene.evening','Avond'),('scene.morning','Goedemorgen'),('scene.movie','Film kijken'),('scene.dinner','Aan tafel'),('scene.relax','Ontspannen'),('scene.read','Lezen'),('scene.sleep','Welterusten'),('script.lights_off','Alle verlichting uit')]
action_icons=['weather-night','weather-sunset-up','movie-open-outline','silverware-fork-knife','sofa-outline','book-open-page-variant-outline','bed-outline','lightbulb-off-outline']
action_states='Object.assign(states,'+json.dumps({entity:{'state':'off' if entity.startswith('script.') else 'scening','attributes':{'friendly_name':name}} for entity,name in action_examples})+');\n'
evcc_states="Object.assign(states,{'sensor.review_evcc_power':sensor(7100,'W'),'binary_sensor.review_evcc_connected':sensor('on'),'binary_sensor.review_evcc_charging':sensor('on'),'sensor.review_evcc_remaining':sensor(5400,'s'),'sensor.review_evcc_target':sensor(80,'%'),'sensor.review_evcc_energy':sensor(12.4,'kWh'),'sensor.review_evcc_cost':sensor(3.18,'€'),'sensor.review_evcc_duration':sensor(6300,'s'),'sensor.review_evcc_solar':sensor(78,'%'),'number.review_evcc_solar':sensor(60,'%',{min:0,max:100,step:10})});\n"
car_states="Object.assign(states,{'sensor.car_status':{state:'Geparkeerd',attributes:{friendly_name:'Status'}},'image.review_car':{state:'available',attributes:{entity_picture:new URL('assets/user-car.png',import.meta.url).href}}});\n"
gallery=inline[1].replace("['car-evcc','Auto met EVCC',{","['car-evcc','Auto met EVCC',{image_entity:'image.review_car',").replace("['car-card','Auto',{percentage_entity:","['car-card','Auto',{image_entity:'image.review_car',field_1_label:'Status',show_field_3:false,percentage_entity:").replace("field_1_entity:'sensor.range'","field_1_entity:'sensor.car_status'").replace('const configs=[',car_states+action_states+evcc_states+'const configs=[').replace("actions:['scene.evening']",'actions:'+json.dumps([{'entity':entity,'icon':'mdi:'+glyph} for (entity,_),glyph in zip(action_examples,action_icons)])).replace("String(220+Math.sin(i/3+j)*100)","String(id==='sensor.review_evcc_power'?5000+Math.sin(i/3)*2100:id==='sensor.temperature'?20.4+Math.sin(i/3)*.8:220+Math.sin(i/3+j)*100)").replace("mean:220+Math.sin(i)*80","mean:id==='sensor.temperature'?20.4+Math.sin(i)*.8:220+Math.sin(i)*80").replace("friendly_name:extra.friendly_name||'Voorbeeld'","friendly_name:extra.friendly_name||({'W':'Vermogen','°C':'Temperatuur','%':'Accu','km':'Actieradius'}[unit]||'Voorbeeld')").replace('window.themeFixtureReady=true;', '''const approved=new Set(['appliance-planner','shopping-card','scene-engine-card','history-graph-card','bar-chart','dynamic-energy-price-card','timeline-card','heatmap-card','overview-card','calendar-card','weather-card','actions-card','car-card','car-evcc','energy-flow-card','room-card','waste-card']);
const main=document.querySelector('main');main.classList.add('review-groups');
const groups={};
for(const [key,title,description] of [['approved','Goedgekeurd','Deze kaarten zijn afzonderlijk door jou beoordeeld en goedgekeurd.'],['pending','Nog te beoordelen','Deze voorbeelden zijn nog niet afzonderlijk goedgekeurd. We pakken ze één voor één op.']]){const section=document.createElement('section');section.className='review-section';section.id=key;const heading=document.createElement('h2');heading.textContent=title;const intro=document.createElement('p');intro.textContent=description;const grid=document.createElement('div');grid.className='review-grid';section.append(heading,intro,grid);main.append(section);const navGroup=document.createElement('div');navGroup.className='review-nav-group';const label=document.createElement('span');label.textContent=title;navGroup.append(label);document.querySelector('nav').append(navGroup);groups[key]={grid,navGroup,heading,count:0};}
for(const [i,r] of records.entries()){const article=r.card.parentElement;article.id='card-'+r.name;const group=groups[approved.has(r.name)?'approved':'pending'];group.grid.append(article);group.count++;article.dataset.reviewStatus=approved.has(r.name)?'approved':'pending';const a=document.createElement('a');a.href='#'+article.id;a.textContent=configs[i][1];group.navGroup.append(a);}
for(const group of Object.values(groups))group.heading.textContent+=' · '+group.count;
const actionRecord=records.find(r=>r.name==='actions-card');
const demoColumns=document.createElement('label');demoColumns.style.cssText='display:flex;align-items:center;gap:10px;margin-top:12px;font-size:12px;color:var(--secondary-text-color)';
demoColumns.textContent='Kolommen (preview)';const countSelect=document.createElement('select');countSelect.id='actions-columns';countSelect.setAttribute('aria-label','Aantal kolommen');countSelect.style.cssText='font:inherit;color:var(--primary-text-color);background:var(--card-background-color);border:1px solid var(--divider-color);border-radius:8px;min-height:44px;padding:6px 12px';
for(let n=1;n<=6;n++){const option=document.createElement('option');option.value=n;option.textContent=n;countSelect.append(option);}countSelect.value=3;
countSelect.addEventListener('change',()=>actionRecord.card.setConfig({...actionRecord.card._config,columns:Number(countSelect.value)}));demoColumns.append(countSelect);actionRecord.card.parentElement.append(demoColumns);
window.themeFixtureReady=true;''')
gallery=gallery.replace("return ids.map((id,j)=>", "if(ids.includes('binary_sensor.review_evcc_connected'))return [[{entity_id:'binary_sensor.review_evcc_connected',state:'on',last_changed:iso(now-2*H)}]];return ids.map((id,j)=>")
gallery=gallery.replace("entities:{soc:'sensor.soc',power:'sensor.power',range:'sensor.range',mode:'select.ev_mode'}", "entities:{soc:'sensor.soc',power:'sensor.review_evcc_power',range:'sensor.range',mode:'select.ev_mode',connected:'binary_sensor.review_evcc_connected',charging:'binary_sensor.review_evcc_charging',remaining_duration:'sensor.review_evcc_remaining',target_soc:'sensor.review_evcc_target',charged_energy:'sensor.review_evcc_energy',session_price:'sensor.review_evcc_cost',charge_duration:'sensor.review_evcc_duration',solar_percentage:'sensor.review_evcc_solar',solar_share:'number.review_evcc_solar'}")
(out/'gallery.js').write_text(js+gallery);(out/'index.html').write_text(s)
files=['dist/eleven-cards.js','cards/home-controls/dist/eleven-home-controls-card.js','cards/room-card/dist/eleven-room-card.js','cards/appliance-planner/dist/eleven-appliance-planner.js','cards/scene-engine-card/dist/eleven-scene-engine-card.js','review/index.html','review/gallery.js','review/ha-stub.js','review/assets/user-car.png']
for f in files:assert (root/f).is_file(),f
